// Throttle duplicate error alerts.
// One alert per failing workflow per THROTTLE_MIN window. Runs that are
// suppressed get counted and reported in the next alert that gets through,
// so an ongoing outage is never silently hidden.
const THROTTLE_MIN = 30;

const store = $getWorkflowStaticData('global');
store.alerts = store.alerts || {};

const item = $input.first().json;
const wfName = (item.workflow && item.workflow.name) || 'unknown';
const now = Date.now();

const rec = store.alerts[wfName] || { last: 0, suppressed: 0 };

if (rec.last && (now - rec.last) / 60000 < THROTTLE_MIN) {
  rec.suppressed = (rec.suppressed || 0) + 1;
  store.alerts[wfName] = rec;
  return [];                 // no items -> Gmail and Twilio never fire
}

const suppressed = rec.suppressed || 0;
store.alerts[wfName] = { last: now, suppressed: 0 };

item.throttle = {
  suppressed,
  note: suppressed
    ? `Plus ${suppressed} more failure${suppressed === 1 ? '' : 's'} in the last ${THROTTLE_MIN} min that were not emailed.`
    : '',
};
return [{ json: item }];

